-- Additive Phase 2 update. Run in a transaction; never deletes existing orders.
SELECT pg_advisory_xact_lock(839472521);

CREATE TABLE IF NOT EXISTS "SchemaUpdates" (
    "Name" text PRIMARY KEY,
    "AppliedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS "Products" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Sku" varchar(64) NOT NULL,
    "Name" varchar(200) NOT NULL,
    "Description" varchar(4000) NOT NULL DEFAULT '',
    "Category" varchar(100) NOT NULL DEFAULT '',
    "UnitOfMeasure" varchar(32) NOT NULL,
    "Dimensions" varchar(500) NOT NULL DEFAULT '',
    "Specifications" varchar(4000) NOT NULL DEFAULT '',
    "Packaging" varchar(1000) NOT NULL DEFAULT '',
    "IsActive" boolean NOT NULL DEFAULT true
);
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = 'Products' AND column_name = 'CompanyKey') THEN
        CREATE UNIQUE INDEX IF NOT EXISTS "IX_Products_Sku" ON "Products" ("Sku");
    END IF;
END $$;
CREATE TABLE IF NOT EXISTS "ProductAliases" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProductId" integer NOT NULL REFERENCES "Products" ("Id") ON DELETE CASCADE,
    "Value" varchar(200) NOT NULL,
    "NormalizedValue" varchar(200) NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_ProductAliases_ProductId_NormalizedValue"
    ON "ProductAliases" ("ProductId", "NormalizedValue");
CREATE INDEX IF NOT EXISTS "IX_ProductAliases_NormalizedValue" ON "ProductAliases" ("NormalizedValue");

ALTER TABLE "WorkOrderItems" ADD COLUMN IF NOT EXISTS "ProductId" integer;
ALTER TABLE "WorkOrderItems" ADD COLUMN IF NOT EXISTS "ProductSkuSnapshot" text NOT NULL DEFAULT '';
ALTER TABLE "WorkOrderItems" ADD COLUMN IF NOT EXISTS "UnitOfMeasureSnapshot" text NOT NULL DEFAULT '';
CREATE INDEX IF NOT EXISTS "IX_WorkOrderItems_ProductId" ON "WorkOrderItems" ("ProductId");
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
        WHERE conname = 'FK_WorkOrderItems_Products_ProductId' AND conrelid = '"WorkOrderItems"'::regclass) THEN
        ALTER TABLE "WorkOrderItems" ADD CONSTRAINT "FK_WorkOrderItems_Products_ProductId"
            FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE RESTRICT;
    END IF;
END $$;

-- One-time compatibility data, not an application product list. Generated codes
-- and 'each' are placeholders for the company to review. Unknown historical SKU
-- and unit snapshots intentionally remain blank.
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM "SchemaUpdates" WHERE "Name" = '002-product-catalog') THEN
        INSERT INTO "Products" ("Sku", "Name", "Description", "Category", "UnitOfMeasure", "Dimensions", "Specifications", "Packaging", "IsActive")
        SELECT 'LEGACY-' || upper(md5(name)), left(name, 200),
            'Existing product imported during catalog setup. Review the generated SKU and default unit.',
            '', 'each', '', '', '', true
        FROM (
            SELECT unnest(ARRAY['Fast Tread', 'BlueDeck', 'SureFit']) AS name
            UNION SELECT "ProductType" FROM "WorkOrderItems" WHERE btrim("ProductType") <> ''
            UNION SELECT "ProductType" FROM "WorkOrders" WHERE btrim("ProductType") <> ''
        ) names
        ON CONFLICT DO NOTHING;

        UPDATE "WorkOrderItems" i SET "ProductId" = p."Id" FROM "Products" p
        WHERE i."ProductId" IS NULL AND p."Sku" = 'LEGACY-' || upper(md5(i."ProductType"));
        INSERT INTO "SchemaUpdates" ("Name") VALUES ('002-product-catalog');
    END IF;
END $$;
